union semun {
    int val;
    struct semid_ds *buf;
    unsigned short *array;
};

int semid = 1234;

// SETVAL: Initialize semaphore 0 to 1 (unlocked)
union semun init_arg;
init_arg.val = 1;
semctl(semid, 0, SETVAL, init_arg);

// GETVAL: Read value of semaphore 0
union semun get_arg;
int val = semctl(semid, 0, GETVAL, get_arg);

// IPC_RMID: Remove the semaphore set
union semun remove_arg;
semctl(semid, 0, IPC_RMID, remove_arg);
